command:
cd /app && python3 - <<'PY'
path = 'parsing/html/writer.go'
s = open(path).read()

old = '''\tcase model.TypeSlice:
\t\tif err := value.RangeSlice(func(_ int, item *model.Value) error {
\t\t\treturn w.writeValue(buf, "", item, 0)
\t\t}); err != nil {
\t\t\treturn nil, err
\t\t}'''
new = '''\tcase model.TypeSlice:
\t\tif err := value.RangeSlice(func(i int, item *model.Value) error {
\t\t\tif i > 0 && !w.options.Compact {
\t\t\t\tbuf.WriteByte('\\n')
\t\t\t}
\t\t\treturn w.writeValue(buf, "", item, 0)
\t\t}); err != nil {
\t\t\treturn nil, err
\t\t}'''
assert old in s
s = s.replace(old, new)

old = '''\t// A map without an element name renders its keys directly.
\tif name == "" {
\t\tfor _, kv := range kvs {
\t\t\tif err := w.writeValue(buf, kv.Key, kv.Value, depth); err != nil {
\t\t\t\treturn err
\t\t\t}
\t\t}
\t\treturn nil
\t}'''
new = '''\t// A map without an element name renders its keys directly.
\tif name == "" {
\t\tfor i, kv := range kvs {
\t\t\tif i > 0 && !w.options.Compact {
\t\t\t\tbuf.WriteByte('\\n')
\t\t\t}
\t\t\tif err := w.writeValue(buf, kv.Key, kv.Value, depth); err != nil {
\t\t\t\treturn err
\t\t\t}
\t\t}
\t\treturn nil
\t}'''
assert old in s
s = s.replace(old, new)
open(path, 'w').write(s)
PY
gofmt -w parsing/html/writer.go && go build ./parsing/html/ && go test ./parsing/html/ 2>&1 | tail -5
